"use client";

import { useEffect } from "react";

type Status =
  | "Not Started"
  | "Drafted"
  | "Ready for Review"
  | "Scheduled"
  | "Published";

type Post = {
  id: string;
  date: string;
  day: string;
  time: string;
  area: string;
  areaUrl: string;
  title: string;
  keyword: string;
  metaDescription: string;
  status: Status;
  statusChangedAt?: string;
  platforms: { gbp: Status; w1: Status; w2: Status; li: Status; fb: Status };
  // Stable pointer into TITLES[area] — set at creation so editing a PostSeed's hook/wording
  // later never orphans an already-saved post (title-string matching alone is fragile: it
  // silently breaks articleParagraphs() for any post whose title no longer matches after an
  // edit). Optional only because posts saved before this field existed need one migration
  // pass to backfill it — see loadData().
  variant?: "guide" | "update" | "considerations" | "spotlight";
  // A real photo specific to THIS post (set when a fresh draft is created for a Not Started
  // area — see photoForPost()). Deliberately stored per-post rather than derived from
  // area+variant: a shared derivation function changes what EVERY post with that area/variant
  // shows the moment the function changes, including already-Scheduled/Published posts no one
  // meant to touch (a real incident, 2026-10-15 — see photoForPost()'s comment). Absent on
  // every pre-existing post, which keeps showing the area's one real Gemini photo exactly as
  // before.
  photoUrl?: string;
  // Hides the post from the normal board view without deleting it — distinct from the
  // modal's permanent "Delete this card", this is meant to be reversible via the same
  // button (it just flips back).
  archived?: boolean;
};

const STATUS_ORDER: Status[] = [
  "Not Started",
  "Drafted",
  "Ready for Review",
  "Scheduled",
  "Published",
];
const STATUS_CLASS: Record<Status, string> = {
  "Not Started": "notstarted",
  Drafted: "drafted",
  "Ready for Review": "review",
  Scheduled: "scheduled",
  Published: "published",
};
const STATUS_LABEL: Record<Status, string> = {
  "Not Started": "Not started",
  Drafted: "Drafted",
  "Ready for Review": "Ready for review",
  Scheduled: "Scheduled",
  Published: "Published",
};

